import os
import re
import hashlib
def task_func(path, delimiter):
    components = re.split(delimiter, path)
    result = []
    for component in components:
        if os.path.isfile(path + delimiter + component):
            with open(path + delimiter + component, 'rb') as f:
                result.append((component, hashlib.sha256(f.read()).hexdigest()))
        else:
            result.append((component, None))
    return result
